#include <filesystem>
#include <fstream>
#include <map>
#include <sstream>

#include "crypto/merkle.h"
#include "crypto/sha3.h"
#include "test/framework.h"
#include "util/hex.h"

using namespace rnet;
using rnet::crypto::Hash256;

namespace {

// The vector file lives beside the source rather than being embedded, because it
// is regenerated by a script and a 600-line array in a header would rot.
std::filesystem::path VectorFile(std::string_view name) {
    for (const auto* root : {"test/vectors", "../test/vectors", "../../test/vectors"}) {
        auto candidate = std::filesystem::path(root) / name;
        if (std::filesystem::exists(candidate)) return candidate;
    }
    return {};
}

// The message the `P` vectors describe. Kept in one place so the test and the
// generator cannot drift apart in what they mean by a given length.
std::vector<uint8_t> PatternedMessage(size_t length) {
    std::vector<uint8_t> message(length);
    for (size_t i = 0; i < length; ++i) message[i] = static_cast<uint8_t>((i * 31 + 7) % 256);
    return message;
}

}  // namespace

// FIPS-202 known-answer vectors. If these ever change, the vendored primitive is
// wrong and every hash in the protocol is wrong with it.
RNET_TEST(Sha3, KnownAnswers) {
    RNET_CHECK_STREQ(util::ToHex(crypto::Sha3_256(std::string_view(""))),
                     "a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a");
    RNET_CHECK_STREQ(util::ToHex(crypto::Sha3_256(std::string_view("abc"))),
                     "3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532");
    RNET_CHECK_STREQ(
        util::ToHex(crypto::Sha3_256(std::string_view("The quick brown fox jumps over the lazy dog"))),
        "69070dda01975c8c120c3aada1b282394e7f032fa9cf32f4cb2259a0897dfc04");
}

// Every hash in this protocol is SHA3-256 — the genesis anchor, Merkle roots over
// the corpus, contribution payloads, checkpoint weights, producer election,
// slashing evidence. All of it rests on a vendored 191-line file that used to be
// verified by the three vectors above.
//
// Three. If that implementation were wrong at some length boundary, nothing here
// would have caught it, and the failure would surface as another node's
// implementation disagreeing — a network split with no symptom to point at.
//
// The vectors below come from CPython's hashlib, which wraps the Keccak reference
// code. A test generated from the code under test proves only self-consistency;
// this is a second implementation disagreeing or not.
RNET_TEST(Sha3, MatchesAnIndependentImplementationAtEveryLength) {
    const auto path = VectorFile("sha3_256.txt");
    if (path.empty()) {
        RNET_FAIL("test/vectors/sha3_256.txt not found — run test/vectors/generate_sha3.py");
    }
    std::ifstream file(path);
    RNET_CHECK(file.is_open());

    size_t patterned = 0, explicit_messages = 0, monte_carlo = 0;
    std::string line;
    while (std::getline(file, line)) {
        if (line.empty() || line[0] == '#') continue;
        std::istringstream fields(line);
        std::string kind;
        fields >> kind;

        if (kind == "P") {
            // Every length from 0 to 600: four full 136-byte absorption blocks and
            // every boundary within them. Padding bugs live at exactly these
            // lengths, and choosing which ones to test by hand is guessing.
            size_t length = 0;
            std::string expected;
            fields >> length >> expected;
            const auto actual = util::ToHex(crypto::Sha3_256(PatternedMessage(length)));
            if (actual != expected) {
                RNET_FAIL("length {}: got {}, expected {}", length, actual, expected);
            }
            ++patterned;

        } else if (kind == "E") {
            // A patterned message can mask a byte-order error by being too
            // regular; explicit random content cannot.
            std::string message_hex, expected;
            fields >> message_hex >> expected;
            auto message = util::FromHex(message_hex);
            RNET_CHECK_OK(message);
            const auto actual = util::ToHex(crypto::Sha3_256(message.value()));
            if (actual != expected) {
                RNET_FAIL("explicit message of {} bytes: got {}, expected {}",
                          message.value().size(), actual, expected);
            }
            ++explicit_messages;

        } else if (kind == "C") {
            ++monte_carlo;
        }
    }

    // The file must actually have been read. A test that silently verifies
    // nothing is worse than no test, because it reports success.
    if (patterned < 600) {
        RNET_FAIL("only {} patterned vectors were checked; the file looks truncated", patterned);
    }
    RNET_CHECK(explicit_messages >= 10);
    RNET_CHECK(monte_carlo >= 4);
}

// A hundred thousand chained hashes, each output the next input.
//
// Single-shot vectors cannot catch state that is not cleared between calls, or a
// permutation wrong in a way that cancels on the first block. Here an error
// anywhere changes everything after it, so agreement at the end is evidence about
// the whole chain rather than about one input.
RNET_TEST(Sha3, MonteCarloChainMatches) {
    const auto path = VectorFile("sha3_256.txt");
    if (path.empty()) {
        RNET_FAIL("test/vectors/sha3_256.txt not found — run test/vectors/generate_sha3.py");
    }
    std::map<int, std::string> checkpoints;
    {
        std::ifstream file(path);
        std::string line;
        while (std::getline(file, line)) {
            if (line.rfind("C ", 0) != 0) continue;
            std::istringstream fields(line);
            std::string kind, digest;
            int round = 0;
            fields >> kind >> round >> digest;
            checkpoints[round] = digest;
        }
    }
    RNET_CHECK(!checkpoints.empty());

    // Seeded with the SHA3-256 of the empty string: a published constant anyone
    // can check, rather than a number chosen here.
    auto digest = util::FromHexFixed<32>(
        "a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a");
    RNET_CHECK_OK(digest);
    Hash256 state = digest.value();

    const int last_round = checkpoints.rbegin()->first;
    for (int round = 0; round <= last_round; ++round) {
        for (int i = 0; i < 1000; ++i) state = crypto::Sha3_256(state);
        const auto expected = checkpoints.find(round);
        if (expected == checkpoints.end()) continue;
        const auto actual = util::ToHex(state);
        if (actual != expected->second) {
            RNET_FAIL("Monte Carlo diverged by round {} ({} chained hashes): got {}, expected {}",
                      round, (round + 1) * 1000, actual, expected->second);
        }
    }
}

RNET_TEST(Sha3, IncrementalMatchesOneShot) {
    const std::string part1 = "ResonanceNet ";
    const std::string part2 = "deterministic training";
    crypto::Sha3Hasher h;
    h.Update(part1).Update(part2);
    RNET_CHECK_EQ(h.Finalize(), crypto::Sha3_256(std::string_view(part1 + part2)));
}

// Boundary lengths around the 136-byte SHA3-256 rate: absorption bugs hide here.
RNET_TEST(Sha3, RateBoundaries) {
    for (size_t len : {size_t{0}, size_t{1}, size_t{135}, size_t{136}, size_t{137}, size_t{272}}) {
        std::vector<uint8_t> data(len, 0xAB);
        crypto::Sha3Hasher h;
        h.Update(data);
        RNET_CHECK_EQ(h.Finalize(), crypto::Sha3_256(data));
    }
}

RNET_TEST(Sha3, DoubleIsHashOfHash) {
    const std::string msg = "Lattica";
    const Hash256 once = crypto::Sha3_256(std::string_view(msg));
    RNET_CHECK_EQ(crypto::Sha3_256d(std::span<const uint8_t>(
                      reinterpret_cast<const uint8_t*>(msg.data()), msg.size())),
                  crypto::Sha3_256(std::span<const uint8_t>(once.data(), once.size())));
}

// Domain separation is what makes an odd promoted node unambiguous; without it a
// leaf could be substituted for an internal node.
RNET_TEST(Merkle, LeafAndNodeAreDomainSeparated) {
    const std::vector<uint8_t> data(64, 0x11);
    const Hash256 leaf = crypto::MerkleLeaf(data);
    Hash256 half{};
    std::copy(data.begin(), data.begin() + 32, half.begin());
    RNET_CHECK(leaf != crypto::MerkleNode(half, half));
}

RNET_TEST(Merkle, SingleLeafRootIsThatLeaf) {
    const std::vector<uint8_t> data{1, 2, 3};
    const Hash256 leaf = crypto::MerkleLeaf(data);
    RNET_CHECK_EQ(crypto::MerkleRoot({leaf}), leaf);
}

// The CVE-2012-2459 shape: a tree whose last node is promoted must NOT collide
// with a tree that genuinely contains that node twice.
RNET_TEST(Merkle, PromotedOddNodeDoesNotCollideWithDuplicate) {
    std::vector<Hash256> three;
    for (uint8_t i = 0; i < 3; ++i) three.push_back(crypto::MerkleLeaf(std::vector<uint8_t>{i}));

    std::vector<Hash256> four = three;
    four.push_back(three[2]);   // duplicate the last leaf

    RNET_CHECK(crypto::MerkleRoot(three) != crypto::MerkleRoot(four));
}

RNET_TEST(Merkle, ProofsVerifyForEveryLeaf) {
    for (size_t n : {size_t{1}, size_t{2}, size_t{3}, size_t{5}, size_t{8}, size_t{9}, size_t{17}}) {
        std::vector<Hash256> leaves;
        for (size_t i = 0; i < n; ++i) {
            leaves.push_back(crypto::MerkleLeaf(std::vector<uint8_t>{static_cast<uint8_t>(i), 0x5A}));
        }
        const Hash256 root = crypto::MerkleRoot(leaves);
        for (size_t i = 0; i < n; ++i) {
            auto proof = crypto::BuildMerkleProof(leaves, i);
            RNET_CHECK_OK(proof);
            if (!crypto::VerifyMerkleProof(leaves[i], proof.value(), root)) {
                RNET_FAIL("proof failed to verify for leaf {} of {}", i, n);
            }
        }
    }
}

RNET_TEST(Merkle, TamperedLeafFailsVerification) {
    std::vector<Hash256> leaves;
    for (uint8_t i = 0; i < 6; ++i) leaves.push_back(crypto::MerkleLeaf(std::vector<uint8_t>{i}));
    const Hash256 root = crypto::MerkleRoot(leaves);

    auto proof = crypto::BuildMerkleProof(leaves, 2);
    RNET_CHECK_OK(proof);

    const Hash256 forged = crypto::MerkleLeaf(std::vector<uint8_t>{0xFF});
    RNET_CHECK(!crypto::VerifyMerkleProof(forged, proof.value(), root));
}

RNET_TEST(Merkle, TruncatedOrPaddedProofIsRejected) {
    std::vector<Hash256> leaves;
    for (uint8_t i = 0; i < 8; ++i) leaves.push_back(crypto::MerkleLeaf(std::vector<uint8_t>{i}));
    const Hash256 root = crypto::MerkleRoot(leaves);

    auto proof = crypto::BuildMerkleProof(leaves, 3);
    RNET_CHECK_OK(proof);

    auto shortened = proof.value();
    shortened.path.pop_back();
    RNET_CHECK(!crypto::VerifyMerkleProof(leaves[3], shortened, root));

    auto padded = proof.value();
    padded.path.push_back(root);
    RNET_CHECK(!crypto::VerifyMerkleProof(leaves[3], padded, root));
}
